double adaptive_midpoint(FunctionPtr f, double a, double b, double precision) {
    // Base case: if interval is too small, return midpoint rule
    if (b - a < 1e-12) {
        return f((a + b) / 2.0) * (b - a);
    }

    // Compute midpoint rule for the whole interval
    double mid = (a + b) / 2.0;
    double h = b - a;
    double whole = f(mid) * h;

    // Compute midpoint rule for the two subintervals
    double left_mid = (a + mid) / 2.0;
    double right_mid = (mid + b) / 2.0;
    double left_integral = f(left_mid) * (h / 2.0);
    double right_integral = f(right_mid) * (h / 2.0);
    double two_subintervals = left_integral + right_integral;

    // Error estimate: difference between whole and sum of subintervals
    double error_estimate = std::abs(whole - two_subintervals);

    // If error is within tolerance, return the more accurate estimate
    if (error_estimate < precision) {
        return two_subintervals;
    }

    // Otherwise, recursively integrate on each subinterval
    return adaptive_midpoint(f, a, mid, precision / 2.0) + 
           adaptive_midpoint(f, mid, b, precision / 2.0);
}

